describe('Sauce Demo Mobile Responsiveness', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
    cy.viewport(375, 860);
  });

  it('should display inventory page and burger menu on mobile viewport after successful login', () => {
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    cy.url().should('include', '/inventory.');
    cy.get('[data-testid="inventory-container"]').should('be.visible');
    cy.get('[data-testid="inventory-list"]').should('be.visible');
    cy.get('[data-testid="inventory-item-sauce-labs-backpack"]').should('be.visible');
    cy.get('[data-testid="inventory-item-sauce-labs-backpack"]').should('contain', '$19.99');

    cy.get('[data-testid="react-burger-menu-btn"]').should('be.visible');
    cy.get('[data-testid="react-burger-menu-btn"]').should('contain', 'Menu');
  });

  it('should open side menu with logout link when burger menu is clicked on mobile viewport', () => {
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="inventory-container"]').should('be.visible');
    cy.get('[data-testid="react-burger-menu-btn"]').click();

    cy.get('[data-testid="bm-menu"]').should('be.visible');
    cy.get('[data-testid="logout-sidebar-link"]').should('be.visible');
    cy.get('[data-testid="logout-sidebar-link"]').should('contain', 'Logout');
    cy.get('[data-testid="reset-sidebar-link"]').should('be.visible');
    cy.get('[data-testid="reset-sidebar-link"]').should('contain', 'Reset');

    cy.get('[data-testid="close-menu"]').click();
    cy.get('[data-testid="bm-menu"]').should('not.exist');
  });
});
